const alertRow  = $('Get Alert').first().json;
const logRows   = $('Aggregate Logs').first().json.logs   || [];
const userRows  = $('Aggregate Users').first().json.users  || [];
const assetRows = $('Aggregate Assets').first().json.assets || [];

const logs = logRows
  .map(l => ({ log_id: l.log_id, log_datetime: l.log_datetime,
               event_type: l.event_type, details: l.details }))
  .sort((a, b) => String(a.log_datetime).localeCompare(String(b.log_datetime)));

const key   = alertRow.context_key;
const user  = alertRow.entity_type === 'user'
            ? (userRows.find(u => u.user_id === key)  || null) : null;
const asset = alertRow.entity_type === 'asset'
            ? (assetRows.find(a => a.asset_id === key) || null) : null;

const toMin = (dt) => {
  const m = String(dt).match(/(\d{1,2}):(\d{2})/);
  return m ? (Number(m[1]) * 60 + Number(m[2])) : null;
};
const times = [alertRow.alert_datetime, ...logs.map(l => l.log_datetime)]
                .map(toMin).filter(t => t !== null);
let outside_working_hours = null;
let timing_detail = 'No user profile for this alert, working hours not applicable';
if (user) {
  const s = toMin(user.work_start), e = toMin(user.work_end);
  const out = times.filter(t => t < s || t > e);
  outside_working_hours = out.length > 0;
  timing_detail = outside_working_hours
    ? out.length + ' of ' + times.length + ' event time(s) fall outside ' + user.work_start + '-' + user.work_end
    : 'All event times fall inside ' + user.work_start + '-' + user.work_end;
}

const expected = String(alertRow.related_logs || '').split(',')
                   .map(s => s.trim()).filter(Boolean);
const found    = logs.map(l => l.log_id);
const missing_logs = expected.filter(id => !found.includes(id));
const alertDay = String(alertRow.alert_datetime).slice(0, 10);
const logs_on_other_day = logs.filter(l => String(l.log_datetime).slice(0, 10) !== alertDay)
                              .map(l => l.log_id);

return [{
  json: {
    case_id: 'CASE-' + alertRow.alert_id,
    alert: {
      alert_id: alertRow.alert_id, alert_datetime: alertRow.alert_datetime,
      alert_type: alertRow.alert_type, user_asset: alertRow.user_asset,
      entity_type: alertRow.entity_type, source: alertRow.source,
      description: alertRow.description, initial_status: alertRow.initial_status
    },
    logs: logs,
    log_count: logs.length,
    user_context: user,
    asset_context: asset,
    timing: { outside_working_hours, timing_detail },
    data_completeness: {
      expected_log_ids: expected, retrieved_log_ids: found,
      missing_logs: missing_logs,
      acting_account_identified: !!user,
      timestamp_inconsistency: logs_on_other_day.length > 0,
      logs_outside_alert_day: logs_on_other_day
    },
    retrieved_at: new Date().toISOString()
  }
}];

