const c  = $('Build Case File').first().json;
const a1 = $('Parse Agent 1 Output').first().json.output;
const a2 = $('Parse Agent 2 Output').first().json.output;
const a3 = $('Parse Agent 3 Output').first().json.output;
const a4 = $json.output;

const forced = [];
if (['High', 'Critical'].includes(a4.severity))      forced.push('High or Critical severity (R12)');
if (Number(a4.confidence) < 0.6)                      forced.push('Low confidence');
if (a2.acting_account_known === false)                forced.push('Acting account not identified');
if ((a3.contradictions || []).length > 0)             forced.push('Contradictory evidence (R11)');
if ((a3.evidence_gaps || []).length > 2)              forced.push('Multiple evidence gaps (R11)');

const order = ['Low', 'Medium', 'High', 'Critical'];
let severity = a4.severity;
let capping  = a4.capping_applied || 'none';
if (Number(a3.evidence_strength) < 0.5 && order.indexOf(severity) > 1) {
  severity = 'Medium';
  capping  = 'Severity capped at Medium in code: evidence_strength below 0.5 (R11)';
}

const requires_human_review = Boolean(a4.requires_human_review) || forced.length > 0;

const record = {
  investigation_id: 'INV-' + c.alert.alert_id + '-' + Date.now(),
  created_at: new Date().toISOString(),
  alert: c.alert,
  severity: severity,
  risk_score: (a4.score_breakdown || []).reduce((sum, f) => sum + (Number(f.points) || 0), 0) || Number(a4.risk_score) || 0,
  score_breakdown: a4.score_breakdown || [],
  capping_applied: capping,
  confidence: Number(a4.confidence) || 0,
  evidence_strength: Number(a3.evidence_strength) || 0,
  investigation_summary: a4.investigation_summary,
  justification: a4.justification,
  rules_applied: a4.rules_applied || [],
  timeline: a1.timeline || [],
  linked_log_ids: c.data_completeness.retrieved_log_ids,
  user_context: a2.user_context,
  asset_context: a2.asset_context,
  outside_working_hours: c.timing.outside_working_hours,
  possible_business_explanation: a2.possible_business_explanation,
  red_flags: a3.red_flags || [],
  benign_indicators: a3.benign_indicators || [],
  evidence_gaps: [...(a3.evidence_gaps || []), ...(a1.missing_evidence || [])],
  contradictions: a3.contradictions || [],
  unresolved_questions: a4.unresolved_questions || [],
  recommended_actions: a4.recommended_actions || [],
  actions_taken_by_system: 'None. This system performs analysis only. All security actions remain with SecureNet security personnel.',
  requires_human_review: requires_human_review,
  human_review_reasons: forced,
  review_priority: a4.review_priority || 'routine'
};

return [{ json: record }];

const raw = $json.output || $json.text || '';
let cleaned = String(raw).trim();

// Strip markdown fences if present
cleaned = cleaned.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();

// Extract just the JSON object even if the model added commentary around it
const firstBrace = cleaned.indexOf('{');
const lastBrace = cleaned.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
  cleaned = cleaned.slice(firstBrace, lastBrace + 1);
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Could not parse Agent 2 output as JSON. Raw text: ' + String(raw).slice(0, 800));
}

return [{ json: { output: parsed } }];

